CREATE TABLE IF NOT EXISTS candidate_registrations (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(150) NOT NULL, phone VARCHAR(30) NOT NULL, email VARCHAR(190) NULL, city VARCHAR(120) NOT NULL, interest VARCHAR(190) NOT NULL, message TEXT NULL, consent TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_candidate_created(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
CREATE TABLE IF NOT EXISTS employer_enquiries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, contact_name VARCHAR(150) NOT NULL, phone VARCHAR(30) NOT NULL, email VARCHAR(190) NULL, city VARCHAR(120) NOT NULL, hiring_needs VARCHAR(190) NOT NULL, message TEXT NULL, consent TINYINT(1) NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX idx_employer_created(created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
